 function autoSize(el){if(!el||el.tagName!=="TEXTAREA")return;el.style.height="0";el.style.height=Math.max(27,Math.min(180,el.scrollHeight))+"px";el.style.overflowY=el.scrollHeight>180?"auto":"hidden"}
 function textControl(id,value,placeholder="",extra=""){return `<textarea rows="1" class="control auto" id="${esc(id)}" placeholder="${esc(placeholder)}" ${extra}>${esc(value??"")}</textarea>`}
 function options(f){try{return JSON.parse(f.options_json||"[]")}catch(_){return []}}
